53	const PROCESSING_FEE = 5;
54	
55	const BASE_PREMIUMS: Record<string, number> = {
56	  sword: 100,
57	  amulet: 60,
58	  staff: 80,
59	  potion: 40,
60	  rune: 25,
61	  moonstone: 25,
62	};
63	
64	const RUNE_BLOCK_SIZE = 3;
65	const RUNE_BLOCK_PREMIUM = 60;
66	
67	const isRune = (item: QuoteItem): boolean => item.type === "rune";
68	
69	const quotePremium = (items: QuoteItem[]): number => {
70	  const runeCount = items.filter(isRune).length;
71	  const runesPremium =
72	    runeCount === RUNE_BLOCK_SIZE
73	      ? RUNE_BLOCK_PREMIUM
74	      : runeCount * BASE_PREMIUMS.rune;
75	  const otherItemsPremium = items
76	    .filter((item) => !isRune(item))
77	    .reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);
78	  const policyBasePremium = runesPremium + otherItemsPremium;
79	  // 10% surcharge computed as base/10 (multiplying by 1.1 introduces float noise)
80	  const firstInsuranceSurcharge = policyBasePremium / 10;
81	  return Math.ceil(policyBasePremium + firstInsuranceSurcharge + PROCESSING_FEE);
82	};
83	
84	export const runScenario = (scenario: Scenario): ScenarioResult => {
85	  const quoteStep = scenario.steps[0] as QuoteStep;
86	  return { results: [{ premium: quotePremium(quoteStep.items) }] };
87	};
