const isRune = (item: QuoteItem): boolean => item.type === "rune";

// Pricing rule: a block of exactly 3 runes costs a flat block premium.
const runesPremium = (runeCount: number): number =>
  runeCount === RUNE_BLOCK_SIZE
    ? RUNE_BLOCK_PREMIUM
    : runeCount * BASE_PREMIUMS.rune;

const quotePremium = (items: QuoteItem[]): number => {
  const runeCount = items.filter(isRune).length;
  const nonRunesPremium = items
    .filter((item) => !isRune(item))
    .reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);
  const policyBasePremium = runesPremium(runeCount) + nonRunesPremium;
